public class MainActivity extends Activity {
    static final String EXTRA_REAUTHORIZE_SCREEN="reauthorize_screen";
    private static final int PICK_TREE=2401,NOTIFY=2402,TERMUX_PERM=2403,SCREEN_CAPTURE=2404,BACKGROUND_PROMPT_VERSION=13; private static final String PREFS="helper_onboarding",PREF_BG_VERSION="background_permission_prompt_version"; private StateStore state; private TextView status,folder,terminalHint; private EditText pair; private CheckBox write,terminal,resourceAdvertise,remoteCompute,screenObserve,clipboardRead,clipboardWrite,computerControl; private TermuxShell shell; private String lastTransportState=""; private boolean updatingUi=false;
    private final BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){String s=i.getStringExtra("state");if(s!=null&&!s.equals(lastTransportState)){lastTransportState=s;status.setText(s);}String code=i.getStringExtra("pair_code");if(code!=null)showPairCode(code,true);}};
    @Override public void onCreate(Bundle b){super.onCreate(b);state=new StateStore(this);buildUi();handleIntent(getIntent());refresh();beginFirstStartPermissions();}
    private void beginFirstStartPermissions(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},NOTIFY);return;}maybeAskBackgroundPermission();}
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grantResults){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==NOTIFY){maybeAskBackgroundPermission();return;}if(requestCode==TERMUX_PERM){boolean granted=grantResults!=null&&grantResults.length>0&&grantResults[0]==PackageManager.PERMISSION_GRANTED;state.setShellReleased(granted);if(terminal!=null)terminal.setChecked(granted);refreshTerminalHint();status.setText(granted?"Local Termux access enabled. It remains private to this device.":"Termux RUN_COMMAND permission denied; local Termux stays closed.");}}
    private void maybeAskBackgroundPermission(){if(Build.VERSION.SDK_INT<23)return;android.content.SharedPreferences prefs=getSharedPreferences(PREFS,MODE_PRIVATE);if(batteryExempt()){prefs.edit().putInt(PREF_BG_VERSION,BACKGROUND_PROMPT_VERSION).apply();return;}if(prefs.getInt(PREF_BG_VERSION,0)>=BACKGROUND_PROMPT_VERSION)return;new AlertDialog.Builder(this).setTitle("Keep AILinux Helper connected?").setMessage("Android can pause the local MCP executor when the screen is off. Allow persistent background operation so paired workspaces stay reachable while the phone is idle. Android will show the system confirmation next.").setCancelable(false).setNegativeButton("Not now",(d,w)->prefs.edit().putInt(PREF_BG_VERSION,BACKGROUND_PROMPT_VERSION).apply()).setPositiveButton("Allow",(d,w)->{if(requestBatteryExemption())prefs.edit().putInt(PREF_BG_VERSION,BACKGROUND_PROMPT_VERSION).apply();}).show();}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleIntent(intent);}
    @Override protected void onResume(){super.onResume();registerReceiver(receiver,new IntentFilter("me.ailinux.workspace.STATE"),Build.VERSION.SDK_INT>=33?Context.RECEIVER_NOT_EXPORTED:0);refresh();}
    @Override protected void onPause(){try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onPause();}
    private TextView text(String value,int color){TextView v=new TextView(this);v.setText(value);v.setTextColor(color);v.setTextSize(16);v.setPadding(0,8,0,8);return v;}
    private void buildUi(){ScrollView scroll=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(40,40,40,40);scroll.addView(l);TextView badge=text("AILinux · TriForce MCP",0xff79c0ff);l.addView(badge);TextView title=text("AILinux Helper",Color.WHITE);title.setTextSize(30);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);l.addView(title);TextView desc=text("The selected folder stays on this device. Native Android routes local shares directly through the foreground MCP executor, independent from browser tab idle/suspension.",0xffb8c1cc);desc.setPadding(0,8,0,24);l.addView(desc);TextView h1=text("1 · Share workspace",Color.WHITE);h1.setTextSize(21);h1.setTypeface(Typeface.DEFAULT,Typeface.BOLD);l.addView(h1);folder=text("",0xffb8c1cc);l.addView(folder);Button choose=button("Choose local folder");choose.setOnClickListener(v->chooseFolder());l.addView(choose);Button clearWorkspace=button("Stop sharing workspace");clearWorkspace.setOnClickListener(v->clearWorkspaceShare());l.addView(clearWorkspace);write=new CheckBox(this);write.setText("Read / Write mode");write.setTextColor(Color.WHITE);write.setChecked("write".equals(state.mode()));l.addView(write);screenObserve=new CheckBox(this);screenObserve.setText("Share display / vision observation");screenObserve.setTextColor(Color.WHITE);screenObserve.setChecked(state.screenObserve());screenObserve.setOnCheckedChangeListener((b,checked)->{if(!updatingUi)onScreenObserveToggle(checked);});l.addView(screenObserve);clipboardRead=new CheckBox(this);clipboardRead.setText("Share clipboard read");clipboardRead.setTextColor(Color.WHITE);clipboardRead.setChecked(state.clipboardRead());clipboardRead.setOnCheckedChangeListener((b,checked)->{if(!updatingUi){state.setClipboardRead(checked);rebindShare("Clipboard read grant updated · rebinding share…");}});l.addView(clipboardRead);clipboardWrite=new CheckBox(this);clipboardWrite.setText("Share clipboard write");clipboardWrite.setTextColor(Color.WHITE);clipboardWrite.setChecked(state.clipboardWrite());clipboardWrite.setOnCheckedChangeListener((b,checked)->{if(!updatingUi){state.setClipboardWrite(checked);rebindShare("Clipboard write grant updated · rebinding share…");}});l.addView(clipboardWrite);computerControl=new CheckBox(this);computerControl.setText("Allow remote device control (tap / swipe / text / navigation)");computerControl.setTextColor(Color.WHITE);computerControl.setChecked(state.computerControl());computerControl.setOnCheckedChangeListener((b,checked)->{if(!updatingUi)onComputerControlToggle(checked);});l.addView(computerControl);Button accessibility=button("Open Android accessibility settings");accessibility.setOnClickListener(v->openAccessibilitySettings());l.addView(accessibility);resourceAdvertise=new CheckBox(this);resourceAdvertise.setText("Advertise device CPU / RAM metadata");resourceAdvertise.setTextColor(Color.WHITE);resourceAdvertise.setChecked(state.resourceAdvertise());resourceAdvertise.setOnCheckedChangeListener((b,checked)->{state.setResourceAdvertise(checked);rebindShare("Device resource advertisement updated · rebinding share…");});l.addView(resourceAdvertise);remoteCompute=new CheckBox(this);remoteCompute.setText("Request isolated TriForce Docker sandbox (internet + ~/workspace; phone shell stays private)");remoteCompute.setTextColor(Color.WHITE);remoteCompute.setChecked(state.remoteCompute());remoteCompute.setOnCheckedChangeListener((b,checked)->{state.setRemoteCompute(checked);rebindShare("Remote-compute preference updated · rebinding share…");});l.addView(remoteCompute);terminal=new CheckBox(this);terminal.setText("Enable local Termux special function (not shared to AI)");terminal.setTextColor(Color.WHITE);terminal.setChecked(state.shellReleased());terminal.setOnCheckedChangeListener((b,checked)->onTerminalToggle(checked));l.addView(terminal);terminalHint=text("",0xff8b949e);terminalHint.setPadding(0,0,0,10);l.addView(terminalHint);refreshTerminalHint();TextView h2=text("2 · Share with AI",Color.WHITE);h2.setTextSize(21);h2.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h2.setPadding(0,26,0,6);l.addView(h2);l.addView(text("Start the executor to create a one-time Share ID. Send that ID to the AI; reconnects use the saved secure lease automatically.",0xff8b949e));pair=new EditText(this);pair.setHint("One-time Share ID");pair.setSingleLine(true);pair.setSelectAllOnFocus(true);pair.setTextIsSelectable(true);pair.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);pair.setFocusable(false);pair.setCursorVisible(false);pair.setTextColor(Color.WHITE);pair.setHintTextColor(0xff8b949e);pair.setBackgroundColor(0xff161b22);pair.setPadding(20,16,20,16);l.addView(pair);LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button copy=button("Copy Share ID");copy.setOnClickListener(v->copyPairCode());actions.addView(copy);l.addView(actions);Button fresh=button("Generate new Share ID");fresh.setOnClickListener(v->beginFreshPairing());l.addView(fresh);Button start=button("Start / reconnect executor");start.setOnClickListener(v->startExecutor(""));l.addView(start);Button stop=button("Disconnect and revoke lease");stop.setOnClickListener(v->startService(new Intent(this,WorkspaceService.class).setAction(WorkspaceService.ACTION_STOP)));l.addView(stop);Button battery=button("Allow persistent background connection");battery.setOnClickListener(v->requestBatteryExemption());l.addView(battery);Button web=button("Open api.ailinux.me/v1/mcp");web.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://api.ailinux.me/v1/mcp"))));l.addView(web);status=text("",0xff63d471);status.setPadding(0,28,0,0);l.addView(status);setContentView(scroll);scroll.setBackgroundColor(0xff0d1117);}
    private TermuxShell shell(){if(shell==null)shell=new TermuxShell(this,state);return shell;}
    private void onTerminalToggle(boolean checked){if(!checked){state.setShellReleased(false);refreshTerminalHint();status.setText("Local Termux access revoked. It is never advertised as a public share capability.");return;}if(!shell().termuxInstalled()){terminal.setChecked(false);state.setShellReleased(false);refreshTerminalHint();status.setText("Termux is not installed. Install the F-Droid/GitHub build, then retry.");return;}if(!shell().permissionGranted()){requestPermissions(new String[]{TermuxShell.PERMISSION_RUN_COMMAND},TERMUX_PERM);return;}state.setShellReleased(true);refreshTerminalHint();status.setText("Local Termux access enabled. It remains a device-local special function and is not advertised to the AI network.");}
    private void refreshTerminalHint(){if(terminalHint==null)return;terminalHint.setText("Shell backend: "+shell().detail()+" · workdir "+shell().workdir(state.tree()));}
    private void onComputerControlToggle(boolean checked){
        state.setComputerControl(checked);
        if(!checked){rebindShare("Remote device control revoked · rebinding share…");return;}
        if(!DeviceControlService.isReady()){
            status.setText("Enable AILinux Helper in Android Accessibility, then return here. Control is not shared until Android reports the service ready.");
            openAccessibilitySettings();
            return;
        }
        rebindShare("Remote device control granted · rebinding share…");
    }
    private void openAccessibilitySettings(){
        try{startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}
        catch(Exception e){status.setText("Open Android Settings → Accessibility → AILinux Helper.");}
    }
    private void onScreenObserveToggle(boolean checked){if(!checked){state.setScreenObserveWanted(false);state.setScreenObserve(false);Intent i=new Intent(this,WorkspaceService.class).setAction(WorkspaceService.ACTION_DISABLE_SCREEN);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Display / vision observation revoked.");return;}MediaProjectionManager manager=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);if(manager==null){updatingUi=true;screenObserve.setChecked(false);updatingUi=false;status.setText("Android MediaProjection service is unavailable.");return;}state.setScreenObserveWanted(true);status.setText("Confirm display sharing in the Android system dialog.");startActivityForResult(manager.createScreenCaptureIntent(),SCREEN_CAPTURE);}
    private Button button(String text){Button b=new Button(this);b.setText(text);b.setAllCaps(false);return b;}
    private void showPairCode(String code,boolean force){if(code==null||code.isEmpty()){if(force)pair.setText("");return;}String current=pair.getText().toString();if(code.equals(current))return;if(!force&&(pair.hasFocus()||pair.hasSelection()||pair.getSelectionStart()!=pair.getSelectionEnd()))return;int start=pair.getSelectionStart(),end=pair.getSelectionEnd();pair.setText(code);if(start>=0&&end>=0){int n=code.length();pair.setSelection(Math.min(start,n),Math.min(end,n));}}
    private void copyPairCode(){String code=pair.getText().toString().trim();if(code.isEmpty())code=state.pairCode();if(code.isEmpty()){status.setText("No Share ID to copy yet.");return;}((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("AILinux Helper Share ID",code));status.setText("Share ID copied.");}
    private void pastePairCode(){android.content.ClipboardManager cm=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(!cm.hasPrimaryClip()||cm.getPrimaryClip()==null||cm.getPrimaryClip().getItemCount()==0){status.setText("Clipboard has no pair code.");return;}CharSequence value=cm.getPrimaryClip().getItemAt(0).coerceToText(this);String code=value==null?"":value.toString().trim().toUpperCase(Locale.ROOT);pair.setText(code);pair.setSelection(code.length());if(!code.isEmpty())state.setPairCode(code);status.setText(code.isEmpty()?"Clipboard has no pair code.":"Pair code pasted.");}
    private void chooseFolder(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(i,PICK_TREE);}
    private void clearWorkspaceShare(){if(state.setTree(null)){refresh();rebindShare("Workspace grant removed · rebinding existing share lease…");}else status.setText("No workspace is currently shared.");}
    private void rebindShare(String message){Intent i=new Intent(this,WorkspaceService.class).setAction(WorkspaceService.ACTION_RECONNECT);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);lastTransportState=message;status.setText(message);}
    @SuppressLint("WrongConstant")
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==SCREEN_CAPTURE){if(resultCode==RESULT_OK&&data!=null){state.setScreenObserveWanted(true);state.setScreenObserve(true);Intent i=new Intent(this,WorkspaceService.class).setAction(WorkspaceService.ACTION_ENABLE_SCREEN).putExtra(WorkspaceService.EXTRA_CAPTURE_RESULT,resultCode).putExtra(WorkspaceService.EXTRA_CAPTURE_DATA,data);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Starting user-approved display observation…");}else{state.setScreenObserveWanted(false);state.setScreenObserve(false);updatingUi=true;if(screenObserve!=null)screenObserve.setChecked(false);updatingUi=false;status.setText("Display sharing was not granted.");}return;}if(requestCode==PICK_TREE&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);try{getContentResolver().takePersistableUriPermission(uri,flags);}catch(SecurityException e){status.setText("Persistent folder permission failed: "+e.getMessage());return;}boolean changed=state.setTree(uri);state.setMode(write.isChecked()?"write":"read_only");refresh();if(changed)rebindShare("Workspace changed · rebinding existing share lease…");else startExecutor("");}}
    private void handleIntent(Intent intent){if(intent==null)return;if(intent.getBooleanExtra(EXTRA_REAUTHORIZE_SCREEN,false)){intent.removeExtra(EXTRA_REAUTHORIZE_SCREEN);new Handler(Looper.getMainLooper()).post(()->onScreenObserveToggle(true));}if(intent.getData()==null)return;Uri u=intent.getData();String handoff="";if("ailinux-workspace".equals(u.getScheme())||"ailinux-helper".equals(u.getScheme())){String host=u.getHost()==null?"":u.getHost();String code=u.getQueryParameter("pair_code");if(code==null)code=u.getQueryParameter("code");if("handoff".equals(host))handoff=code==null?"":code;else if("pair".equals(host)&&code!=null)state.setPairCode(code);}else if("api.ailinux.me".equals(u.getHost())){String p=u.getQueryParameter("pair_code");if(p!=null)state.setPairCode(p);}refresh();if(handoff!=null&&!handoff.isEmpty())startExecutor(handoff);}
    private boolean batteryExempt(){if(Build.VERSION.SDK_INT<23)return true;PowerManager pm=getSystemService(PowerManager.class);return pm!=null&&pm.isIgnoringBatteryOptimizations(getPackageName());}
    private boolean requestBatteryExemption(){if(Build.VERSION.SDK_INT<23){status.setText("Battery optimization restrictions do not apply on this Android version.");return true;}if(batteryExempt()){status.setText("Persistent background connection is already allowed by Android.");return true;}try{startActivity(new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:"+getPackageName())));status.setText("Confirm persistent background operation in the Android system dialog.");return true;}catch(Exception e){try{startActivity(new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS));status.setText("Select AILinux Helper and allow unrestricted background operation.");return true;}catch(Exception ignored){status.setText("Open Android Settings → Apps → AILinux Helper → Battery → Unrestricted.");return false;}}}
    private void beginFreshPairing(){
        if(state.tree()==null&&!state.resourceAdvertise()&&!state.remoteCompute()&&!state.clipboardRead()&&!state.clipboardWrite()&&!state.screenObserve()&&!(state.computerControl()&&DeviceControlService.isReady())){status.setText("Choose a workspace or enable an available native share first.");return;}
        state.setMode(write.isChecked()?"write":"read_only");
        state.clearCredentials();
        showPairCode("",true);
        Intent i=new Intent(this,WorkspaceService.class).setAction(WorkspaceService.ACTION_NEW_PAIR);
        if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);
        lastTransportState="Requesting a new one-time Share ID…";status.setText(lastTransportState);
    }
    private void startExecutor(String handoff){state.setMode(write.isChecked()?"write":"read_only");if(terminal!=null&&!terminal.isChecked())state.setShellReleased(false);String p=pair.getText().toString().trim().toUpperCase(Locale.ROOT);if(!p.isEmpty()&&state.resumeToken().isEmpty())state.setPairCode(p);boolean hasHandoff=handoff!=null&&!handoff.isEmpty();Intent i=new Intent(this,WorkspaceService.class).setAction(hasHandoff?WorkspaceService.ACTION_START:WorkspaceService.ACTION_RECONNECT);if(hasHandoff)i.putExtra(WorkspaceService.EXTRA_HANDOFF,handoff);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);lastTransportState="Executor requested…";status.setText(lastTransportState);}
    private void refresh(){Uri tree=state.tree();folder.setText(tree==null?"No folder shared":"Workspace: "+tree);String savedPair=state.pairCode();if(savedPair==null||savedPair.isEmpty()){if(!pair.hasFocus())showPairCode("",true);}else showPairCode(savedPair,false);updatingUi=true;write.setChecked("write".equals(state.mode()));if(screenObserve!=null)screenObserve.setChecked(state.screenObserve()||state.screenObserveWanted());if(clipboardRead!=null)clipboardRead.setChecked(state.clipboardRead());if(clipboardWrite!=null)clipboardWrite.setChecked(state.clipboardWrite());if(computerControl!=null)computerControl.setChecked(state.computerControl());if(resourceAdvertise!=null)resourceAdvertise.setChecked(state.resourceAdvertise());if(remoteCompute!=null)remoteCompute.setChecked(state.remoteCompute());if(terminal!=null){terminal.setChecked(state.shellReleased());refreshTerminalHint();}updatingUi=false;if(status.getText().length()==0)status.setText(tree==null?"Choose a folder once; Android keeps the URI grant.":(batteryExempt()?"Ready. Persistent background connection allowed.":"Ready. For reliable screen-off operation, allow the persistent background connection below."));}
}
